import fs from 'node:fs';
import path from 'node:path';
import zlib from 'node:zlib';

const RELEASE='0.25.0';
const payload={"src/App.tsx":"","src/views/ItCosts.tsx":"","src/views/FinancialOptimization.tsx":"","src/views/FinancialOptimization.css":"","src/lib/storage.ts":"","src/data/seed.json":"","package.json":"","README.md":"","RELEASE_NOTES.md":"","RELEASE_NOTES_0.25.md":"","README_NASADENIE_0.25.txt":"","FINANCIAL_ACTIONS_0.25.md":""};
const root=process.cwd();
const packagePath=path.join(root,'package.json');
if(!fs.existsSync(packagePath)){console.error('ERROR: Spustite installer v koreni projektu (chyba package.json).');process.exit(1)}
const pkg=JSON.parse(fs.readFileSync(packagePath,'utf8'));
console.log(`Aktualizácia IS Riadenie odboru ${pkg.version||'?'} -> ${RELEASE}`);
const stamp=new Date().toISOString().replace(/[:.]/g,'-');
const backup=path.join(root,`backup-before-v0250-${stamp}`);
fs.mkdirSync(backup,{recursive:true});
for(const rel of Object.keys(payload)){const src=path.join(root,rel);if(fs.existsSync(src)){const dst=path.join(backup,rel);fs.mkdirSync(path.dirname(dst),{recursive:true});fs.copyFileSync(src,dst)}}
for(const [rel,data] of Object.entries(payload)){const target=path.join(root,rel);fs.mkdirSync(path.dirname(target),{recursive:true});fs.writeFileSync(target,zlib.gunzipSync(Buffer.from(data,'base64')));console.log('WRITE',rel)}
for(const cache of ['dist','.vite','node_modules/.vite']){const target=path.join(root,cache);if(fs.existsSync(target))fs.rmSync(target,{recursive:true,force:true})}
const checkPkg=JSON.parse(fs.readFileSync(packagePath,'utf8'));
const itCosts=fs.readFileSync(path.join(root,'src/views/ItCosts.tsx'),'utf8');
const opt=fs.readFileSync(path.join(root,'src/views/FinancialOptimization.tsx'),'utf8');
if(checkPkg.version!==RELEASE||!itCosts.includes('FinancialOptimization')||!opt.includes('Financial Actions & Optimization')){console.error('ERROR: Verifikácia v0.25.0 zlyhala.');process.exit(2)}
console.log(`VERIFIED: release ${RELEASE} - Financial Actions & Optimization je nainštalovaný.`);
console.log('Backup:',backup);
